INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (131, 'en', 'Returns the name of the window on which the script is acting.', NULL, 584);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (132, 'en', 'Returns a value representing the orientation of the window on which the script is acting.', NULL, 585);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (133, 'en', 'Returns the style of the window on which the script is acting.', NULL, 586);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (134, 'en', 'Returns the vertical distance, in points, of the outer edge of the window on which the script is acting, relative to the top edge of the screen in Windows, or the bottom edge of the menu bar in macOS.', NULL, 587);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (135, 'en', 'Returns the Universally Unique Identifier (UUID) of the active window.', NULL, 588);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (136, 'en', 'Returns 1 (true) if the window is visible; returns 0 (false) if the window is hidden using Hide Window.', NULL, 589);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (137, 'en', 'Returns the width, in points, of the window on which the script is acting.', NULL, 590);
INSERT INTO "get_constant_localizations" ("get_constant_id", "locale", "purpose", "summary", "help_page_id") VALUES (138, 'en', 'Returns the zoom percentage of the current window.', NULL, 591);
